function getKeywordWeight(keyword: string): number {
    if (STRONG_SIGNAL_KEYWORDS.has(keyword)) return 8;
    if (MEDIUM_SIGNAL_KEYWORDS.has(keyword)) return 3;
    if (LOW_SIGNAL_KEYWORDS.has(keyword)) return 0.2;
    if (keyword.includes('定理') || keyword.includes('公式') || keyword.includes('方法') || keyword.includes('判别') || keyword.includes('条件')) return 5;
    if (keyword.length >= 6) return 3;
    if (keyword.length >= 3) return 1.5;
    return 0.5;
}

function getKeywordMatchScore(topic: string, key: string, discipline: any) {
    const matchedKeywords = getDisciplineKeywords(key, discipline).filter(keyword => topic.includes(keyword));
    return {
        key,
        score: matchedKeywords.reduce((sum, keyword) => sum + getKeywordWeight(keyword), 0),
        matchedCount: matchedKeywords.length,
        matchedLength: matchedKeywords.reduce((sum, keyword) => sum + keyword.length, 0),
        longestKeywordLength: matchedKeywords.reduce((max, keyword) => Math.max(max, keyword.length), 0)
    };
}

// 主题识别函数
export function identifyDiscipline(topic: string): string {
    const bestKeywordMatch = Object.entries(MATH_DISCIPLINES)
        .map(([key, discipline]) => getKeywordMatchScore(topic, key, discipline))
        .filter(score => score.matchedCount > 0)
        .sort((a, b) => {
            if (b.score !== a.score) return b.score - a.score;
            if (b.matchedLength !== a.matchedLength) return b.matchedLength - a.matchedLength;
            if (b.matchedCount !== a.matchedCount) return b.matchedCount - a.matchedCount;
            return b.longestKeywordLength - a.longestKeywordLength;
        })[0];

    if (bestKeywordMatch) return bestKeywordMatch.key;

    if (topic.includes('概形') || topic.includes('概型') || topic.includes('Spec') || topic.includes('Proj') || topic.includes('层上同调') || topic.includes('凝聚层') || topic.includes('Serre对偶') || topic.includes('étale')) return 'algebraic-geometry-schemes';
    if (topic.includes('代数曲线') || topic.includes('代数曲面') || topic.includes('Riemann-Roch') || topic.includes('椭圆曲线') || topic.includes('曲面分类') || topic.includes('K3曲面') || topic.includes('有理曲面') || topic.includes('亏格') || topic.includes('除子')) return 'algebraic-geometry-curves';
    if (topic.includes('代数几何') || topic.includes('代数簇') || topic.includes('代数集') || topic.includes('Hilbert零点定理') || topic.includes('Nullstellensatz') || topic.includes('Zariski拓扑') || topic.includes('射影代数几何') || topic.includes('射影几何') || topic.includes('射影簇') || topic.includes('齐次坐标') || topic.includes('齐次理想') || topic.includes('Cremona') || topic.includes('仿射代数几何') || topic.includes('仿射簇') || topic.includes('仿射代数集') || topic.includes('消元理想')) return 'algebraic-geometry-classical';

    // fallback: score-based matching missed; use coarse topic signals
    if (topic.includes('几何')) {
        if (topic.includes('微分')) return 'geometry-differential';
        if (topic.includes('解析')) return 'geometry-analytic';
        if (topic.includes('立体') || topic.includes('空间')) return 'geometry-solid';
        return 'geometry-plane';
    }
    if (topic.includes('微分方程')) {
        if (topic.includes('稳定性') || topic.includes('分岔') || topic.includes('极限环')) return 'ode-qualitative';
        if (topic.includes('边值') || topic.includes('Sturm')) return 'ode-boundary-value';
        if (topic.includes('渐近') || topic.includes('摄动')) return 'ode-perturbation';
        return 'ode-qualitative';
    }
    if (topic.includes('偏微分') || topic.includes('PDE')) {
        if (topic.includes('调和')) return 'pde-elliptic';
        if (topic.includes('热') || topic.includes('抛物')) return 'pde-parabolic';
        if (topic.includes('波动') || topic.includes('双曲')) return 'pde-hyperbolic';
        return 'pde-distribution';
    }
    if (topic.includes('数论') || topic.includes('质数')) {
        if (topic.includes('代数整数') || topic.includes('代数数')) return 'number-theory-algebraic';
        if (topic.includes('模形式')) return 'number-theory-modular';
        if (topic.includes('丢番图') || topic.includes('不定方程')) return 'number-theory-diophantine';
        return 'number-theory-basic';
    }
    if (topic.includes('混沌') || topic.includes('动力系统')) {
        if (topic.includes('Hamilton') || topic.includes('辛')) return 'dynamical-hamiltonian';
        if (topic.includes('遍历')) return 'dynamical-ergodic';
        return 'dynamical-chaos';
    }
    return 'algebra-equation'; // 默认

}

// 获取学科特定的难度指导
export function getDisciplineGuidance(topic: string, difficulty: string): string {
    const disciplineKey = identifyDiscipline(topic);
    const discipline = MATH_DISCIPLINES[disciplineKey];
    const levelGuidance = discipline.levels[difficulty] || discipline.levels.intermediate;

    return `
【学科识别】：${discipline.name}
【难度等级要求】：
${levelGuidance}

【关键提示】：
- 题目必须严格遵守上述难度定义
- 不可越级使用高难度概念
- 数据应体现数学的真实性和严谨性
`;
}

// 根据知识点 key 获取难度指导（新增）
export function getDisciplineGuidanceByKey(key: string, difficulty: string): string {
    const discipline = MATH_DISCIPLINES[key];
    if (!discipline) {
        // 如果 key 不存在，回退到 topic 识别
        return getDisciplineGuidance(key, difficulty);
    }
    const levelGuidance = discipline.levels[difficulty] || discipline.levels.intermediate;

    return `
【学科识别】：${discipline.name}
【难度等级要求】：
${levelGuidance}

【关键提示】：
- 题目必须严格遵守上述难度定义
- 不可越级使用高难度概念
- 数据应体现数学的真实性和严谨性
`;
}

